"use client"

import * as React from "react"
import {
  animate,
  motion,
  useInView,
  useMotionValue,
  useReducedMotion,
  useTransform,
  type AnimationPlaybackControls,
  type HTMLMotionProps,
} from "motion/react"
import { cn } from "@/lib/utils"

const DEFAULT_COLORS = ["#c679c4", "#fa3d1d", "#ffb005", "#e1e1fe", "#0358f7"]
const BAND_HALF = 17
const SWEEP_START = -BAND_HALF
const SWEEP_END = 100 + BAND_HALF

const sweepEase = (t: number) => (t < 0.5 ? 4 * t ** 3 : 1 - (-2 * t + 2) ** 3 / 2)

function buildGradient(pos: number, colors: string[], textColor: string) {
  const bandStart = pos - BAND_HALF
  const bandEnd = pos + BAND_HALF
  if (bandStart >= 100) {
    return `linear-gradient(90deg, ${textColor}, ${textColor})`
  }
  const count = colors.length
  const parts: string[] = []
  if (bandStart > 0) {
    parts.push(`${textColor} 0%`, `${textColor} ${bandStart.toFixed(2)}%`)
  }
  colors.forEach((color, index) => {
    const pct = count === 1 ? pos : bandStart + (index / (count - 1)) * BAND_HALF * 2
    parts.push(`${color} ${pct.toFixed(2)}%`)
  })
  if (bandEnd < 100) {
    parts.push(`transparent ${bandEnd.toFixed(2)}%`, "transparent 100%")
  }
  return `linear-gradient(90deg, ${parts.join(", ")})`
}

function measureWidths(element: HTMLElement, texts: string[]) {
  const ghost = element.cloneNode() as HTMLElement
  Object.assign(ghost.style, {
    position: "absolute",
    visibility: "hidden",
    pointerEvents: "none",
    width: "auto",
    whiteSpace: "nowrap",
  })
  element.parentElement?.appendChild(ghost)
  const widths = texts.map((t) => {
    ghost.textContent = t
    return ghost.getBoundingClientRect().width
  })
  ghost.remove()
  return widths
}

export interface DiaTextRevealProps
  extends Omit<HTMLMotionProps<"span">, "children"> {
  text: string | string[]
  colors?: string[]
  textColor?: string
  duration?: number
  delay?: number
  repeat?: boolean
  repeatDelay?: number
  triggerOnView?: boolean
  once?: boolean
  fixedWidth?: boolean
}

export function DiaTextReveal({
  text,
  colors = DEFAULT_COLORS,
  textColor = "var(--foreground)",
  duration = 1.5,
  delay = 0,
  repeat = false,
  repeatDelay = 0.5,
  triggerOnView = true,
  once = true,
  fixedWidth = false,
  className,
  style,
  ...props
}: DiaTextRevealProps) {
  const spanRef = React.useRef<HTMLSpanElement>(null)
  const [activeIndex, setActiveIndex] = React.useState(0)
  const [measuredWidths, setMeasuredWidths] = React.useState<number[]>([])

  const texts = React.useMemo(
    () => (Array.isArray(text) ? text : [text]),
    [text]
  )
  const isMulti = texts.length > 1

  const activeIndexRef = React.useRef(0)
  const controlsRef = React.useRef<AnimationPlaybackControls | null>(null)
  const timerRef = React.useRef<ReturnType<typeof setTimeout> | null>(null)
  const hasPlayedRef = React.useRef(false)
  const playRef = React.useRef<() => void>(() => {})

  const sweepPos = useMotionValue(SWEEP_START)
  const reduceMotion = useReducedMotion()
  const inView = useInView(spanRef, { once, amount: 0.1 })
  const isVisible = triggerOnView ? inView : true

  const backgroundImage = useTransform(sweepPos, (pos) =>
    buildGradient(pos, colors, textColor)
  )

  const clearCycle = React.useCallback(() => {
    controlsRef.current?.stop()
    controlsRef.current = null
    if (timerRef.current) {
      clearTimeout(timerRef.current)
      timerRef.current = null
    }
  }, [])

  const play = React.useCallback(() => {
    clearCycle()
    sweepPos.set(SWEEP_START)
    controlsRef.current = animate(sweepPos, SWEEP_END, {
      duration,
      delay,
      ease: sweepEase,
      onComplete() {
        if (!repeat || texts.length === 0) return
        timerRef.current = setTimeout(() => {
          const next = (activeIndexRef.current + 1) % texts.length
          activeIndexRef.current = next
          setActiveIndex(next)
          playRef.current()
        }, repeatDelay * 1000)
      },
    })
  }, [clearCycle, delay, duration, repeat, repeatDelay, sweepPos, texts.length])

  React.useEffect(() => {
    playRef.current = play
  }, [play])

  // measure text widths on mount or when texts list changes
  React.useEffect(() => {
    if (!spanRef.current || !isMulti) {
      return
    }
    const widths = measureWidths(spanRef.current, texts)
    setMeasuredWidths(widths)
  }, [texts, isMulti])

  // trigger animation according to in-view and motion preferences
  React.useEffect(() => {
    if (reduceMotion) {
      clearCycle()
      sweepPos.set(SWEEP_END)
      return
    }

    if (!isVisible) {
      if (!once) {
        hasPlayedRef.current = false
      }
      return
    }

    if (once && hasPlayedRef.current) return

    hasPlayedRef.current = true
    play()

    return clearCycle
  }, [clearCycle, isVisible, once, play, reduceMotion, sweepPos])

  const fixedW =
    isMulti && fixedWidth && measuredWidths.length > 0
      ? Math.max(...measuredWidths)
      : undefined
  const animatedW =
    isMulti && !fixedWidth && measuredWidths[activeIndex] != null
      ? measuredWidths[activeIndex]
      : undefined

  return (
    <motion.span
      ref={spanRef}
      data-slot="dia-text-reveal"
      className={cn(
        "translate-y-[-2px] text-transparent bg-clip-text [background-size:100%_100%] leading-[100%]",
        isMulti && "inline-block overflow-hidden whitespace-nowrap align-bottom",
        className
      )}
      style={{
        backgroundImage: reduceMotion ? undefined : (backgroundImage as unknown as string),
        ...(fixedW != null ? { width: fixedW } : {}),
        ...style,
      }}
      animate={animatedW != null ? { width: animatedW } : undefined}
      transition={{ duration: 0.4, ease: [0.4, 0, 0.2, 1] }}
      {...props}
    >
      {texts[activeIndex] ?? ""}
    </motion.span>
  )
}
